selector_to_html = {"a[href=\"../dispatch_user_guide/configure-backend-selection.html#environment-variables\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u73af\u5883\u53d8\u91cf<a class=\"headerlink\" href=\"#environment-variables\" title=\"Link to this heading\">#</a></h2><p>\u73af\u5883\u53d8\u91cf\u53ef\u4ee5\u8986\u76d6\u5e73\u53f0\u914d\u7f6e\u4e2d\u7684\u7279\u5b9a\u9879\u3002\u5982\u679c\u672a\u8bbe\u7f6e\uff0c\u5219\u4f7f\u7528\u5e73\u53f0\u914d\u7f6e\u6587\u4ef6\u4e2d\u7684\u503c\u3002</p>", "a[href=\"../overview/overview.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">vllm-plugin-FL \u6982\u89c8<a class=\"headerlink\" href=\"#vllm-plugin-fl\" title=\"Link to this heading\">#</a></h1><p>vllm-plugin-FL \u662f <a class=\"reference external\" href=\"https://github.com/vllm-project/vllm\">vLLM</a> \u63a8\u7406/\u670d\u52a1\u6846\u67b6\u7684\u63d2\u4ef6\uff0c\u6784\u5efa\u5728 <a class=\"reference external\" href=\"https://flagos.io\">FlagOS</a> \u8fd9\u4e00\u7edf\u4e00\u7684\u5f00\u6e90 AI \u7cfb\u7edf\u8f6f\u4ef6\u6808\u4e4b\u4e0a\u3002vllm-plugin-FL \u6269\u5c55\u4e86 vLLM \u5728\u591a\u79cd\u786c\u4ef6\u73af\u5883\u4e0b\u7684\u80fd\u529b\u4e0e\u6027\u80fd\u3002\u5728\u4e0d\u6539\u53d8 vLLM \u539f\u6709\u63a5\u53e3\u548c\u4f7f\u7528\u65b9\u5f0f\u7684\u524d\u63d0\u4e0b\uff0c\u540c\u4e00\u6761\u547d\u4ee4\u5373\u53ef\u5728\u4e0d\u540c\u82af\u7247\u4e0a\u8fd0\u884c\u6a21\u578b\u63a8\u7406/\u670d\u52a1\u3002vllm-plugin-FL \u53ef\u4e0e FlagOS \u7684\u5176\u4ed6\u7ec4\u4ef6\u914d\u5408\u4f7f\u7528\uff0c\u5305\u62ec\u7edf\u4e00\u7b97\u5b50\u5e93 <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagGems\">FlagGems</a>\u3001\u7edf\u4e00\u901a\u4fe1\u5e93 <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagCX\">FlagCX</a> \u548c\u7edf\u4e00\u7f16\u8bd1\u5668 <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree\">FlagTree</a>\u3002</p><p>vllm-plugin-FL \u901a\u8fc7 Docker \u955c\u50cf\u5b89\u88c5\uff0c\u968f\u540e\u5728\u76ee\u6807\u82af\u7247\u4e0a\u628a vLLM \u4e0e FlagOS \u7684\u7b97\u5b50\u5e93\u3001\u901a\u4fe1\u5e93\u548c\u7f16\u8bd1\u5668\u6808\u96c6\u6210\u8d77\u6765\u3002\u5b89\u88c5\u6d41\u7a0b\u53c2\u89c1<a class=\"reference internal\" href=\"../getting_started/getting-started.html\"><span class=\"std std-doc\">\u5feb\u901f\u5165\u95e8</span></a>\uff0c\u63d2\u4ef6\u63d0\u4f9b\u7684\u80fd\u529b\u53c2\u89c1<a class=\"reference internal\" href=\"../overview/features.html\"><span class=\"std std-doc\">\u7279\u6027</span></a>\u3002</p>", "a[href=\"requirements.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u8981\u6c42<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><h2>\u8f6f\u4ef6\u8981\u6c42<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2><p>\u4e0b\u8868\u6c47\u603b\u4e86\u5404\u7248\u672c vllm-plugin-FL \u6240\u9700\u7684\u8f6f\u4ef6\u53ca\u5176\u7248\u672c\uff1a</p>", "a[href=\"#cuda\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">CUDA \u989d\u5916\u8bbe\u7f6e<a class=\"headerlink\" href=\"#cuda\" title=\"Link to this heading\">#</a></h3><p>\u672c\u8282\u8bf4\u660e\u5982\u4f55\u901a\u8fc7\u8bbe\u7f6e\u73af\u5883\u53d8\u91cf\u4f7f\u7528 CUDA \u8fd0\u884c\u63a8\u7406\u4efb\u52a1\u3002</p><p>\u7b97\u5b50\u8c03\u5ea6\u73af\u5883\u53d8\u91cf\u8bf7\u53c2\u89c1 <a class=\"reference internal\" href=\"../dispatch_user_guide/configure-backend-selection.html#environment-variables\"><span class=\"std std-ref\">\u73af\u5883\u53d8\u91cf</span></a>\u3002</p>", "a[href=\"#id1\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u5b89\u88c5\u8fd0\u884c\u63a8\u7406\u4efb\u52a1\u6240\u9700\u7684\u8f6f\u4ef6<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><h2>\u4ece Docker \u955c\u50cf\u5b89\u88c5<a class=\"headerlink\" href=\"#docker\" title=\"Link to this heading\">#</a></h2><p>vllm-plugin-FL \u901a\u8fc7\u9884\u6784\u5efa\u7684 Docker \u955c\u50cf\u5b89\u88c5\u3002\u53d7\u652f\u6301\u7684\u7248\u672c\u4e0e\u786c\u4ef6\u5e73\u53f0\u89c1<a class=\"reference internal\" href=\"requirements.html\"><span class=\"std std-doc\">\u8981\u6c42</span></a>\u3002</p>", "a[href=\"#ascend\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u534e\u4e3a Ascend \u989d\u5916\u8bbe\u7f6e<a class=\"headerlink\" href=\"#ascend\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#id3\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">\u4f7f\u7528\u539f\u751f CUDA \u7b97\u5b50<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h4><p>\u5982\u679c\u60a8\u60f3\u4f7f\u7528\u539f\u59cb\u7684 CUDA \u7b97\u5b50\uff0c\u53ef\u4ee5\u8bbe\u7f6e\u4ee5\u4e0b\u73af\u5883\u53d8\u91cf\u3002</p>", "a[href=\"#id2\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">\u4f7f\u7528 CUDA \u901a\u4fe1\u5e93<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#id4\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u8c03\u5ea6\u7b97\u5b50<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">#</a></h3><p>\u5982\u679c\u9700\u8981\uff0c\u60a8\u4e5f\u53ef\u4ee5\u8c03\u5ea6\u7b97\u5b50\u3002</p><p>\u6982\u5ff5\u76f8\u5173\u4fe1\u606f\u8bf7\u53c2\u89c1 <a class=\"reference internal\" href=\"../overview/overview.html\"><span class=\"std std-doc\">vllm-plugin-FL \u6982\u89c8</span></a>\u3002\n\u914d\u7f6e\u76f8\u5173\u4fe1\u606f\u8bf7\u53c2\u89c1 <a class=\"reference internal\" href=\"../dispatch_user_guide/dispatch-user-guide.html\"><span class=\"std std-doc\">\u7b97\u5b50\u8c03\u5ea6\u7528\u6237\u6307\u5357</span></a>\u3002</p>", "a[href=\"../dispatch_user_guide/dispatch-user-guide.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u7b97\u5b50\u8c03\u5ea6\u7528\u6237\u6307\u5357<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p>\u672c\u6307\u5357\u4ecb\u7ecd\u5982\u4f55\u4f7f\u7528\u7b97\u5b50\u8c03\u5ea6\u7cfb\u7edf\uff0c\u8be5\u7cfb\u7edf\u5728 FlagGems\u3001\u5382\u5546\u7279\u5b9a\u5b9e\u73b0\u548c PyTorch \u53c2\u8003\u5b9e\u73b0\u4e4b\u95f4\u8fdb\u884c\u9009\u62e9\u3002\u9009\u62e9\u9075\u5faa\u4f18\u5148\u7ea7\u5c42\u7ea7\uff0c\u4ece\u9ad8\u5230\u4f4e\uff1a</p>", "a[href=\"#docker\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u4ece Docker \u955c\u50cf\u5b89\u88c5<a class=\"headerlink\" href=\"#docker\" title=\"Link to this heading\">#</a></h2><p>vllm-plugin-FL \u901a\u8fc7\u9884\u6784\u5efa\u7684 Docker \u955c\u50cf\u5b89\u88c5\u3002\u53d7\u652f\u6301\u7684\u7248\u672c\u4e0e\u786c\u4ef6\u5e73\u53f0\u89c1<a class=\"reference internal\" href=\"requirements.html\"><span class=\"std std-doc\">\u8981\u6c42</span></a>\u3002</p>", "a[href=\"#version-compatibility\"]": "<p id=\"version-compatibility\">\u8bf7\u9009\u62e9\u4e0e vLLM \u7248\u672c\u5339\u914d\u7684\u5206\u652f\uff0c\u5206\u652f\u4e0e vLLM \u7248\u672c\u5fc5\u987b\u6210\u5bf9\u4f7f\u7528\uff1a</p>", "a[href=\"run-inference-task.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u8fd0\u884c\u63a8\u7406\u4efb\u52a1<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p><a class=\"reference internal\" href=\"install.html\"><span class=\"std std-doc\">\u5b89\u88c5</span></a>\u597d vLLM \u548c vllm-plugin-FL \u540e\uff0c\u60a8\u53ef\u4ee5\u901a\u8fc7\u4e24\u79cd\u65b9\u5f0f\u8fd0\u884c\u63a8\u7406\uff1a\u79bb\u7ebf\u6279\u91cf\u63a8\u7406\uff08\u5728 Python \u811a\u672c\u4e2d\u76f4\u63a5\u52a0\u8f7d\u6a21\u578b\uff09\u6216\u670d\u52a1\u63a8\u7406\uff08\u542f\u52a8 API \u670d\u52a1\u5668\u5e76\u53d1\u9001\u8bf7\u6c42\uff09\u3002\u8bf7\u9009\u62e9\u9002\u5408\u60a8\u7528\u4f8b\u7684\u65b9\u5f0f\u3002</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
